  const runCounts=new Map();for(const task of allTasks){if(task.automation_run_id)runCounts.set(task.automation_run_id,(runCounts.get(task.automation_run_id)||0)+1)}
  const runs=[...runCounts.keys()].sort();const selectedTask=allTasks.find(task=>task.orchestration_task_id===state.taskManagement.selectedId);
  if(!state.taskManagement.graphRunId||!runCounts.has(state.taskManagement.graphRunId))state.taskManagement.graphRunId=selectedTask?.automation_run_id||runs[0]||null;
  runSelect.replaceChildren();if(!runs.length){const option=document.createElement("option");option.value="";option.textContent="対象 Run なし";runSelect.append(option);runSelect.disabled=true}else{runSelect.disabled=false;for(const runId of runs){const option=document.createElement("option");option.value=runId;option.textContent=`Run ${runId} (${runCounts.get(runId)} Task)`;runSelect.append(option)}runSelect.value=state.taskManagement.graphRunId}
