function renderTaskGraphNode(node){const classes=["task-graph-node",`state-${String(node.state).replace(/[^a-z_]/g,"")}`];if(node.critical)classes.push("critical");if(node.blockedBy.length)classes.push("propagated");if(node.cycle)classes.push("cycle");if(node.external)classes.push("external");if(node.id===state.taskManagement.selectedId)classes.push("selected");const group=taskGraphSvgElement("g",{class:classes.join(" "),transform:`translate(${node.x} ${node.y})`,tabindex:node.external?"-1":"0",role:node.external?"img":"button","data-task-id":node.id,"aria-label":`${node.title}、状態 ${statusLabel(node.state)}、前置 Task ${node.predecessorCount} 件${node.blockedBy.length?`、上流阻断 ${node.blockedBy.length} 件`:""}`});const title=taskGraphSvgElement("title");title.textContent=`${node.id}\n状態: ${statusLabel(node.state)}\n前置 Task: ${node.predecessorCount}${node.blockingReason?`\n阻断理由: ${node.blockingReason}`:""}${node.blockedBy.length?`\n上流阻断元: ${node.blockedBy.join(", ")}`:""}`;const rect=taskGraphSvgElement("rect",{width:node.width,height:node.height,rx:"10"});const heading=taskGraphSvgElement("text",{x:"12",y:"22",class:"task-graph-node-title"});heading.textContent=node.external?`参照外 · ${shortTaskGraphText(node.title,20)}`:`#${node.sequence} ${shortTaskGraphText(node.title,22)}`;const status=taskGraphSvgElement("text",{x:"12",y:"45",class:"task-graph-node-state"});status.textContent=statusLabel(node.state);const detail=taskGraphSvgElement("text",{x:"12",y:"65",class:"task-graph-node-meta"});detail.textContent=node.blockedBy.length?`上流阻断 ${node.blockedBy.length} · 前置 ${node.predecessorCount}`:node.cycle?`循環依存 · 前置 ${node.predecessorCount}`:`前置 Task ${node.predecessorCount}`;group.append(title,rect,heading,status,detail);if(!node.external){const select=()=>selectTaskManagementTask(node.id).catch(error=>notify(error.message,true));group.addEventListener("click",select);group.addEventListener("keydown",event=>{if(event.key==="Enter"||event.key===" "){event.preventDefault();select()}})}return group}
function taskGraphSvgElement(name,attributes={}){const node=document.createElementNS("http://www.w3.org/2000/svg",name);for(const [key,value] of Object.entries(attributes))node.setAttribute(key,String(value));return node}
function addTaskGraphMarker(defs,id,className){const marker=taskGraphSvgElement("marker",{id,viewBox:"0 0 10 10",refX:"9",refY:"5",markerWidth:"7",markerHeight:"7",orient:"auto-start-reverse"});marker.append(taskGraphSvgElement("path",{d:"M 0 0 L 10 5 L 0 10 z",class:`task-graph-marker ${className}`}));defs.append(marker)}
function shortTaskGraphText(value,limit){const textValue=String(value||"");return textValue.length>limit?`${textValue.slice(0,limit-1)}…`:textValue}
function taskDetailSection(title){const section=document.createElement("section");section.className="task-detail-section";const heading=document.createElement("h4");heading.textContent=title;section.append(heading);return section}
function renderTaskManagementDetail(task){const box=$("taskManagementDetail");box.replaceChildren();if(!task){box.className="task-management-detail empty";box.textContent="Task を選択すると詳細と履歴を表示します。";return}box.className="task-management-detail";const heading=document.createElement("div");heading.className="task-detail-heading";const names=document.createElement("div");const title=document.createElement("h3");title.textContent=task.title;const meta=document.createElement("p");meta.textContent=`${task.orchestration_task_id} · Run ${task.automation_run_id} · 変更 ${task.change_request_id}`;names.append(title,meta);heading.append(names,badge(task.effective_state||task.state,task.effective_state||task.state));box.append(heading);const definition=taskDetailSection("Task Definition");const instruction=document.createElement("p");instruction.textContent=task.instruction;const definitionMeta=document.createElement("small");definitionMeta.className="task-detail-meta";definitionMeta.textContent=`Action ${task.action} · Kind ${task.task_kind} · Protocol ${task.protocol_version} · 優先度 ${task.priority||100} · 試行 ${task.attempt_count}/${task.max_attempts}`;const capabilities=document.createElement("div");capabilities.className="task-capabilities";for(const value of task.required_capabilities||[]){const item=document.createElement("code");item.textContent=value;capabilities.append(item)}definition.append(instruction,definitionMeta,capabilities);box.append(definition);if(task.blocking_reason){const blocker=document.createElement("p");blocker.className="task-blocking-reason";blocker.textContent=`阻断理由: ${task.blocking_reason}`;box.append(blocker)}box.append(renderTaskDependencies(task),renderTaskClaims(task),renderTaskResults(task),renderTaskEvents(task),renderTaskManagementActions(task))}
function renderTaskDependencies(task){const section=taskDetailSection("依存関係");const list=document.createElement("ul");list.className="task-detail-list";if(!(task.dependencies||[]).length){const item=document.createElement("li");item.textContent="依存 Task なし";list.append(item)}for(const dependency of task.dependencies||[]){const item=document.createElement("li");item.textContent=dependency;list.append(item)}section.append(list);return section}
