function renderTaskResults(task){const section=taskDetailSection("Result");const list=document.createElement("ul");list.className="task-detail-list";if(!(task.results||[]).length){const item=document.createElement("li");item.textContent="Result はまだありません。";list.append(item)}for(const result of task.results||[]){const item=document.createElement("li");const row=document.createElement("div");row.className="task-detail-row";const summary=document.createElement("strong");summary.textContent=result.summary;row.append(summary,badge(result.outcome,result.outcome));const detail=document.createElement("small");detail.textContent=`${result.submitted_by} · ${taskTime(result.submitted_at)} · Artifact ${(result.artifact_refs||[]).join("、")||"なし"} · Evidence ${JSON.stringify(result.evidence||{})}`;item.append(row,detail);list.append(item)}section.append(list);return section}
function renderTaskEvents(task){const section=taskDetailSection("Event 履歴");const list=document.createElement("ol");list.className="task-detail-list";if(!(task.events||[]).length){const item=document.createElement("li");item.textContent="Event はまだありません。";list.append(item)}for(const event of task.events||[]){const item=document.createElement("li");const row=document.createElement("div");row.className="task-detail-row";const type=document.createElement("strong");type.textContent=`#${event.sequence} ${event.event_type}`;const time=document.createElement("span");time.textContent=taskTime(event.created_at);row.append(type,time);const detail=document.createElement("small");detail.textContent=`${event.actor} · ${JSON.stringify(event.payload||{})}`;item.append(row,detail);list.append(item)}section.append(list);return section}
function renderTaskManagementActions(task){const section=taskDetailSection("人工操作");section.classList.add("task-management-actions");const note=document.createElement("p");note.textContent="Claim は担当を示すだけで、人工承認の Evidence にはなりません。Lease Token はページメモリだけに保持します。";const reason=document.createElement("label");reason.textContent="Release／Requeue 理由";const input=document.createElement("input");input.id="taskManagementActionReason";input.maxLength=2000;input.placeholder="操作理由を入力";input.value=state.taskManagementActionReasons[task.orchestration_task_id]||"";input.addEventListener("input",()=>{state.taskManagementActionReasons[task.orchestration_task_id]=input.value});reason.append(input);const actions=document.createElement("div");actions.className="execution-actions";if(task.lease_expired&&state.taskManagementLease?.taskId===task.orchestration_task_id)state.taskManagementLease=null;const lease=state.taskManagementLease?.taskId===task.orchestration_task_id?state.taskManagementLease:null;if(["ready","blocked","failed"].includes(task.state)){const priority=document.createElement("label");priority.textContent="Queue 優先度";const priorityInput=document.createElement("input");priorityInput.type="number";priorityInput.min="1";priorityInput.max="1000";priorityInput.value=String(task.priority||100);priorityInput.className="task-priority-input";priority.append(priorityInput);const priorityButton=document.createElement("button");priorityButton.type="button";priorityButton.className="secondary";priorityButton.textContent="優先度を保存";priorityButton.addEventListener("click",()=>updateManagedTaskPriority(task,priorityInput).catch(error=>notify(error.message,true)));actions.append(priority,priorityButton)}if((task.effective_state||task.state)==="ready"&&!lease){const claim=document.createElement("button");claim.type="button";claim.className="primary";claim.textContent="人として Claim";claim.addEventListener("click",()=>claimManagedTask(task).catch(error=>notify(error.message,true)));actions.append(claim)}if(lease){const release=document.createElement("button");release.type="button";release.className="secondary";release.textContent="Task を Release";release.addEventListener("click",()=>releaseManagedTask(task).catch(error=>notify(error.message,true)));actions.append(release)}if(["blocked","failed"].includes(task.state)){const requeue=document.createElement("button");requeue.type="button";requeue.className="primary";requeue.textContent="Task を Requeue";requeue.addEventListener("click",()=>requeueManagedTask(task).catch(error=>notify(error.message,true)));actions.append(requeue)}section.append(note,reason,actions);return section}
async function claimManagedTask(task){const executorId=actor();const result=await api(`/api/v1/orchestration-tasks/${encodeURIComponent(task.orchestration_task_id)}/claim`,{method:"POST",headers:{"X-OperaMind-Actor":executorId},body:JSON.stringify({executor_kind:"human",capabilities:task.required_capabilities||[],project_id:task.project_id})});state.taskManagementLease={taskId:task.orchestration_task_id,executorId,leaseToken:result.task.lease_token};replaceManagedTask(result.task);renderTaskManagement();notify("OrchestrationTask を人として Claim しました")}
async function releaseManagedTask(task){const lease=state.taskManagementLease?.taskId===task.orchestration_task_id?state.taskManagementLease:null,reason=(state.taskManagementActionReasons[task.orchestration_task_id]||"").trim();if(!lease)throw new Error("この画面で取得した Lease がありません");if(!reason)throw new Error("Release 理由を入力してください");const result=await api(`/api/v1/orchestration-tasks/${encodeURIComponent(task.orchestration_task_id)}/release`,{method:"POST",headers:{"X-OperaMind-Actor":lease.executorId},body:JSON.stringify({lease_token:lease.leaseToken,reason})});state.taskManagementLease=null;delete state.taskManagementActionReasons[task.orchestration_task_id];replaceManagedTask(result.task);renderTaskManagement();notify("OrchestrationTask を Release しました")}
