async function updateManagedTaskPriority(task,input){const priority=Number(input.value);if(!Number.isInteger(priority)||priority<1||priority>1000)throw new Error("優先度は 1～1000 で入力してください");const result=await api(`/api/v1/orchestration-tasks/${encodeURIComponent(task.orchestration_task_id)}/priority`,{method:"PATCH",headers:{"X-OperaMind-Actor":actor()},body:JSON.stringify({priority})});replaceManagedTask(result.task);renderTaskManagement();notify("Queue 優先度を更新しました")}

async function loadProjects(){const body=await api("/api/v1/projects");const select=$("projectSelect");select.replaceChildren();for(const project of body.projects){const option=document.createElement("option");option.value=project.project_id;option.textContent=`${project.name} (${project.change_request_count})`;select.append(option)}if(body.projects.length){state.projectId=select.value;await Promise.all([loadRequests(),loadTaskManagement(),loadUiKnowledgeReviews(),loadUnresolvedEvidence()])}else await loadTaskManagement()}
async function loadRequests(){if(!state.projectId)return;const body=await api(`/api/v1/change-requests?project_id=${encodeURIComponent(state.projectId)}`);const list=$("requestList");list.replaceChildren();if(!body.count){const empty=document.createElement("div");empty.className="empty";empty.textContent="変更要件はまだありません";list.append(empty)}for(const item of body.change_requests){const button=document.createElement("button");button.className=`request-item${item.change_request_id===state.requestId?" active":""}`;const title=document.createElement("strong");title.textContent=item.requirement_text||item.change_request_id;const meta=document.createElement("span");meta.textContent=`${statusLabel(item.document_review_status)} · ${item.submitted_by}`;button.append(title,meta);button.addEventListener("click",()=>selectRequest(item.change_request_id));list.append(button)}}

async function loadUiKnowledgeReviews(){if(!state.projectId)return;const selected=state.projectId;const value=await api(`/api/v1/projects/${encodeURIComponent(selected)}/ui-knowledge/reviews`);if(selected!==state.projectId)return;state.uiKnowledge=value;renderUiKnowledgeReviews(value)}
async function loadUnresolvedEvidence(){if(!state.projectId)return;const selected=state.projectId;const value=await api(`/api/v1/projects/${encodeURIComponent(selected)}/unresolved-evidence`);if(selected!==state.projectId)return;state.unresolvedEvidence=value;renderUnresolvedEvidence(value)}
function unresolvedCategoryLabel(value){return ({call_target:"呼び出し先",endpoint_route:"画面・API Route",data_table:"データテーブル",entity_mapping:"Entity 対応",config_key:"設定キー",navigation_target:"遷移先",generic_relation:"その他の関係"})[value]||value}
function unresolvedReasonLabel(value){return ({target_definition_missing:"対象定義が見つかりません",target_ambiguous:"候補が複数あり一意に決められません",runtime_observation_missing:"実行時 Route 観測がありません",external_reference_unverified:"外部依存を検証できていません",dynamic_reference:"動的な値を静的解析だけでは確定できません",unresolved_reference:"候補はありますが解析器による一意の証明がありません",resolved_unique:"一意の証拠で解決しました"})[value]||value}
