function renderCaseOperation(operation){const row=document.createElement("article");row.className="case-operation";const title=document.createElement("strong");title.textContent=`${operation.case_title} · ${testCaseFieldLabel(operation.field)}`;const diff=document.createElement("div");diff.className="case-operation-diff";const before=document.createElement("span");before.className="case-operation-before";before.textContent=operation.summary_before;const arrow=document.createElement("b");arrow.textContent="→";const after=document.createElement("span");after.className="case-operation-after";after.textContent=operation.summary_after;diff.append(before,arrow,after);row.append(title,diff);return row}
