function copilotEventLabel(value){return ({published:"Web から通知",claimed:"VS Code が受信",claim_recovered:"認領期限切れから復旧",accepted:"ユーザーが確認",context_loaded:"MCP Context 取得",command_recorded:"テスト結果を回収",diff_recorded:"Diff を回収",result_recorded:"commit 結果を回収",cancelled:"タスクを取消",failed:"実行失敗",reanalysis_required:"再分析が必要"})[value]||value}
