async function publishCopilotTask(){if(!state.requestId||!state.projectId||!state.case)throw new Error("変更要件を選択してください");const workspace=$("copilotWorkspace").value.trim(),summary=$("copilotTaskSummary").value.trim(),progress=state.case.progress;if(!workspace)throw new Error("隔離 linked worktree を入力してください");if(!summary)throw new Error("Coding Plan の概要を入力してください");sessionStorage.setItem("operamind.copilotWorkspace",workspace);const result=await api(`/api/v1/change-requests/${encodeURIComponent(state.requestId)}/copilot-task`,{method:"POST",headers:{"X-OperaMind-Actor":actor(),"Idempotency-Key":key("copilot-task")},body:JSON.stringify({project_id:state.projectId,edit_packet_id:progress.edit_packet.id,approval_grant_id:progress.approval_grant.id,workspace_root:workspace,task_summary:summary})});state.copilotTask=result;notify("VS Code local Bridge に Coding Plan を通知しました");renderCopilotBridge(progress)}
