function renderTimeline(steps){const box=$("timeline");box.replaceChildren();for(const step of steps){const row=document.createElement("div");row.className=`timeline-item ${step.status}`;const dot=document.createElement("span");dot.className="dot";const label=document.createElement("strong");label.textContent=step.label;row.append(dot,label,badge(step.status,step.status));box.append(row)}}
function renderEvidence(evidence){const box=$("evidenceList");box.replaceChildren();const all=[...evidence.command_results.map(item=>({...item,kind:"コマンド結果"})),...evidence.ui_evidence.map(item=>({...item,kind:"UI 証跡"}))];if(!all.length){box.className="empty";box.textContent="実行証跡はまだありません。";return}box.className="";for(const item of all){const card=document.createElement("div");card.className="evidence-card";const title=document.createElement("strong");title.textContent=item.kind;const body=document.createElement("code");body.textContent=` ${statusLabel(item.status||item.evidence_type||"")} · ${item.stdout_sha256||item.sha256||""}`;card.append(title,body);box.append(card)}}
function renderImpact(report){const box=$("impactList");box.replaceChildren();if(!report){show("impactPanel",false);return}show("impactPanel",true);for(const item of report.items||[]){const card=document.createElement("article");card.className="impact-card";const info=document.createElement("div");const title=document.createElement("h3");title.textContent=actionLabel(item.recommended_action);const detail=document.createElement("p");detail.textContent=`${item.target_path} · 影響度 ${statusLabel(item.impact_level)}`;info.append(title,detail);const choices=document.createElement("div");choices.className="decision";for(const [value,label] of [["approve","承認"],["reject","却下"]]){const l=document.createElement("label");const radio=document.createElement("input");radio.type="radio";radio.name=`impact-${item.impact_item_id}`;radio.value=value;if(value==="approve")radio.checked=true;l.append(radio,label);choices.append(l)}card.dataset.itemId=item.impact_item_id;card.append(info,choices);box.append(card)}}
function renderAutomation(run){const summary=$("automationSummary"),timeline=$("automationTimeline"),events=$("automationEvents"),stateBadge=$("automationState");summary.replaceChildren();timeline.replaceChildren();events.replaceChildren();if(!run){summary.className="automation-summary empty";summary.textContent="一括編成はまだ開始されていません。";stateBadge.textContent="未開始";stateBadge.className="badge neutral";show("resumeAutomation",false);show("humanTaskControls",false);$("startAutomation").disabled=false;return}stateBadge.textContent=statusLabel(run.status);stateBadge.className=`badge ${statusClass(run.status)}`;summary.className="automation-summary";const title=document.createElement("strong");title.textContent=`現在: ${run.current_stage_label}`;const next=document.createElement("span");next.textContent=run.blocking_reason?`阻断理由: ${run.blocking_reason}`:`次の操作: ${automationActionLabel(run.next_action)}`;summary.append(title,next);const task=run.current_task;if(task){const taskLine=document.createElement("span");taskLine.textContent=`実行 Task #${task.sequence} · ${task.action} · ${statusLabel(task.effective_state||task.state)} · Capability ${(task.required_capabilities||[]).join(" / ")}`;summary.append(taskLine)}renderHumanTaskControls(task);renderAutomationTimeline(run.steps||[]);for(const event of run.events||[]){const item=document.createElement("li");const seq=document.createElement("span");seq.className="event-sequence";seq.textContent=`#${event.sequence}`;const message=document.createElement("span");message.textContent=event.message;item.append(seq,message,badge(event.status,event.status));events.append(item)}show("resumeAutomation",run.status!=="completed");$("startAutomation").disabled=true}
