function automationActionLabel(action){return ({confirm_requirement:"変更要件を確認",prepare_document_with_copilot:"VS Code GitHub Copilot で設計書を生成",revise_document_with_copilot:"設計書を再修正",confirm_document_diff:"下の設計書差分を確認",prepare_canonical_analysis:"Canonical 影響分析を生成",confirm_impact:"下の影響項目を確認",generate_orchestration:"コード・テスト編成を生成",apply_code_change_with_copilot:"VS Code GitHub Copilot でコードを変更",issue_approval_grant:"実行範囲を承認",start_test_data_execution:"テストデータ実行を開始",run_ui_verification:"実ブラウザ UI 検証を実行",refresh:"実行状態を更新",resolve_blocker:"阻断理由を解消"})[action]||action||"なし"}
function renderHumanTaskControls(task){if(task?.lease_expired&&state.humanTaskLease?.taskId===task.orchestration_task_id)state.humanTaskLease=null;const lease=state.humanTaskLease&&state.humanTaskLease.taskId===task?.orchestration_task_id?state.humanTaskLease:null;if(!task){show("humanTaskControls",false);return}show("humanTaskControls");const effective=task.effective_state||task.state;show("claimHumanTask",effective==="ready"&&!lease);show("heartbeatHumanTask",Boolean(lease));show("releaseHumanTask",Boolean(lease));show("humanTaskResultForm",Boolean(lease));show("humanTaskRequeueForm",["blocked","failed"].includes(task.state));const claim=task.claims?.find(value=>value.status==="active");$("humanTaskNote").textContent=lease?`担当中: ${lease.executorId}。Lease Token はこの画面のメモリだけに保持します。`:claim?`担当中: ${claim.executor_kind} / ${claim.executor_id}。期限切れ後に別の実行者が Claim できます。`:`Task #${task.sequence} を人として Claim できます。Claim しただけでは承認になりません。`}
async function claimHumanTask(){const task=state.automation?.current_task;if(!task)throw new Error("担当する Task がありません");const executorId=actor();const result=await api(`/api/v1/orchestration-tasks/${encodeURIComponent(task.orchestration_task_id)}/claim`,{method:"POST",headers:{"X-OperaMind-Actor":executorId},body:JSON.stringify({executor_kind:"human",capabilities:task.required_capabilities||[],project_id:task.project_id})});state.humanTaskLease={taskId:task.orchestration_task_id,executorId,leaseToken:result.task.lease_token};state.automation.current_task=result.task;renderAutomation(state.automation);notify("Task を担当しました。Lease を維持しながら既存の業務操作を実行してください")}
