for(const [id,fn] of [["refreshTaskManagement",loadTaskManagement],["applyTaskFilters",loadTaskManagement],["startAutomation",startAutomation],["resumeAutomation",resumeAutomation],["claimHumanTask",claimHumanTask],["heartbeatHumanTask",heartbeatHumanTask],["releaseHumanTask",releaseHumanTask],["submitHumanTaskResult",submitHumanTaskResult],["requeueHumanTask",requeueHumanTask],["confirmDiff",()=>reviewDiff("confirmed")],["reviseDiff",()=>reviewDiff("revision_requested")],["confirmImpact",confirmImpact],["orchestrateChange",orchestrateChange],["modifyTestCase",submitTestCaseModification],["issueGrant",issueGrant],["publishCopilotTask",publishCopilotTask],["cancelCopilotTask",cancelCopilotTask],["retryCopilotTask",retryCopilotTask],["refreshCase",loadCase],["refreshUiKnowledge",loadUiKnowledgeReviews],["refreshUnresolvedEvidence",loadUnresolvedEvidence],["refreshEnvironmentDiagnostics",loadEnvironmentDiagnostics],["startTestData",startTestDataRun],["rerunTestData",rerunTestDataRun],["recoverTestData",()=>recoverTestDataRun()],["failureRecover",()=>recoverTestDataRun("failureRecoveryReason")],["failureRerun",rerunTestDataRun]])$(id).addEventListener("click",async()=>{try{await fn()}catch(error){notify(error.message,true)}});
$("bindAutomationCase").addEventListener("click",async()=>{try{await bindAutomationCase()}catch(error){notify(error.message,true)}});
Promise.all([loadEnvironmentDiagnostics(),loadReadiness(),loadProjects()]).catch(error=>notify(error.message,true));
